create or replace function public.srk_worker_get_my_wallet_summary()
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_worker uuid;
  v_ledger numeric(14,2);
  v_reserved numeric(14,2);
  v_net numeric(14,2);
  v_held integer;
  v_cash_due numeric(14,2);
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode='42501';
  end if;
  select id into v_worker
  from public.srk_worker_profiles
  where user_id=auth.uid()
  limit 1;
  if v_worker is null then
    raise exception 'Approved worker profile not found' using errcode='P0002';
  end if;

  select coalesce(sum(balance_effect),0)::numeric(14,2)
    into v_ledger
  from public.srk_worker_wallet_ledger
  where worker_id=v_worker;

  select coalesce(sum(coalesce(approved_amount,requested_amount)),0)::numeric(14,2)
    into v_reserved
  from public.srk_worker_payout_requests
  where worker_id=v_worker
    and status in ('requested','under_review','approved');

  select count(*)::integer into v_held
  from public.srk_worker_earnings
  where worker_id=v_worker and settlement_status='held';

  select greatest(0,-coalesce(sum(balance_effect),0))::numeric(14,2)
    into v_cash_due
  from public.srk_worker_wallet_ledger
  where worker_id=v_worker
    and entry_type in ('cash_commission_due','cash_commission_collected');

  v_net := v_ledger-v_reserved;
  return jsonb_build_object(
    'worker_id',v_worker,
    'currency','INR',
    'ledger_balance',v_ledger,
    'reserved_payout_amount',v_reserved,
    'available_for_payout',greatest(0,v_net),
    'recovery_debt',greatest(0,-v_net),
    'net_balance_after_reservations',v_net,
    'cash_commission_outstanding',v_cash_due,
    'held_earning_count',v_held,
    'payout_blocked',v_held>0
  );
end;
$$;
revoke all on function public.srk_worker_get_my_wallet_summary() from public, anon;
grant execute on function public.srk_worker_get_my_wallet_summary() to authenticated;

create unique index if not exists srk_worker_paid_payout_reference_uidx
on public.srk_worker_payout_requests (lower(btrim(payment_reference)))
where status='paid' and payment_reference is not null;

create or replace function public.srk_worker_request_payout(p_amount numeric)
returns public.srk_worker_payout_requests
language plpgsql
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_worker uuid;
  v_available numeric(12,2);
  v_reserved numeric(12,2);
  v_payout public.srk_worker_payout_requests%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode='42501';
  end if;
  if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then
    raise exception 'Payout amount must be positive and limited to two decimal places' using errcode='22023';
  end if;

  select id into v_worker
  from public.srk_worker_profiles
  where user_id=auth.uid()
  for update;
  if not found then raise exception 'Worker profile not found'; end if;

  if exists(select 1 from public.srk_worker_earnings
            where worker_id=v_worker and settlement_status='held') then
    raise exception 'Payout is temporarily held while a refund/dispute is reviewed';
  end if;

  select coalesce(sum(balance_effect),0)
    into v_available
  from public.srk_worker_wallet_ledger
  where worker_id=v_worker;

  select coalesce(sum(coalesce(approved_amount,requested_amount)),0)
    into v_reserved
  from public.srk_worker_payout_requests
  where worker_id=v_worker
    and status in ('requested','under_review','approved');

  if p_amount>v_available-v_reserved then
    raise exception 'Payout exceeds unreserved available balance';
  end if;

  insert into public.srk_worker_payout_requests(worker_id,requested_amount,status)
  values(v_worker,p_amount,'requested')
  returning * into v_payout;
  return v_payout;
end;
$$;

create or replace function public.srk_admin_review_worker_payout(
  p_payout_id uuid,
  p_approve boolean,
  p_approved_amount numeric default null,
  p_note text default null
)
returns public.srk_worker_payout_requests
language plpgsql
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_payout public.srk_worker_payout_requests%rowtype;
  v_available numeric(12,2);
  v_reserved numeric(12,2);
  v_amount numeric(12,2);
begin
  if auth.uid() is null or not public.srk_has_admin_permission('payouts.manage') then
    raise exception 'Payout management permission required' using errcode='42501';
  end if;
  if p_approve is null then
    raise exception 'Approval decision is required' using errcode='22023';
  end if;
  if p_approved_amount is not null and
     (p_approved_amount<=0 or p_approved_amount<>round(p_approved_amount,2)) then
    raise exception 'Approved amount must be positive and limited to two decimal places' using errcode='22023';
  end if;

  select * into v_payout
  from public.srk_worker_payout_requests
  where id=p_payout_id
  for update;
  if not found or v_payout.status not in ('requested','under_review') then
    raise exception 'Payout request not reviewable';
  end if;

  perform 1 from public.srk_worker_profiles where id=v_payout.worker_id for update;

  if exists(select 1 from public.srk_worker_earnings
            where worker_id=v_payout.worker_id and settlement_status='held') then
    raise exception 'Worker payout is held due to refund/dispute review';
  end if;

  if not p_approve then
    update public.srk_worker_payout_requests
    set status='rejected',reviewed_at=clock_timestamp(),
        reviewed_by=auth.uid(),admin_note=p_note
    where id=p_payout_id returning * into v_payout;
    return v_payout;
  end if;

  v_amount:=coalesce(p_approved_amount,v_payout.requested_amount);

  select coalesce(sum(balance_effect),0)
    into v_available
  from public.srk_worker_wallet_ledger
  where worker_id=v_payout.worker_id;

  select coalesce(sum(coalesce(approved_amount,requested_amount)),0)
    into v_reserved
  from public.srk_worker_payout_requests
  where worker_id=v_payout.worker_id
    and id<>p_payout_id
    and status in ('requested','under_review','approved');

  if v_amount<=0 or v_amount>v_payout.requested_amount or v_amount>v_available-v_reserved then
    raise exception 'Approved amount exceeds unreserved available balance';
  end if;

  update public.srk_worker_payout_requests
  set status='approved',approved_amount=v_amount,
      reviewed_at=clock_timestamp(),reviewed_by=auth.uid(),admin_note=p_note
  where id=p_payout_id returning * into v_payout;
  return v_payout;
end;
$$;

revoke all on function public.srk_worker_request_payout(numeric) from public, anon;
grant execute on function public.srk_worker_request_payout(numeric) to authenticated;
revoke all on function public.srk_admin_review_worker_payout(uuid,boolean,numeric,text) from public, anon;
grant execute on function public.srk_admin_review_worker_payout(uuid,boolean,numeric,text) to authenticated;

create or replace function public.srk_admin_commission_refund_period_breakdown(
  p_period text default 'monthly',
  p_anchor_date date default ((now() at time zone 'Asia/Kolkata')::date)
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_anchor date := coalesce(p_anchor_date,(now() at time zone 'Asia/Kolkata')::date);
  v_start date;
  v_end date;
  v_result jsonb;
begin
  if auth.uid() is null or not public.srk_has_admin_permission('payments.read') then
    raise exception 'Payment dashboard permission required' using errcode='42501';
  end if;
  if p_period not in ('daily','monthly','yearly') then
    raise exception 'Period must be daily, monthly or yearly' using errcode='22023';
  end if;

  if p_period='daily' then
    v_start:=v_anchor; v_end:=v_anchor;
  elsif p_period='monthly' then
    v_start:=date_trunc('month',v_anchor)::date;
    v_end:=(v_start+interval '1 month - 1 day')::date;
  else
    v_start:=make_date(extract(year from v_anchor)::int,1,1);
    v_end:=make_date(extract(year from v_anchor)::int,12,31);
  end if;

  with refund_period as (
    select r.id,r.booking_id,r.commission_refund_amount,
      (r.recorded_at at time zone 'Asia/Kolkata')::date refund_recorded_date,
      (coalesce(b.payment_verified_at,b.created_at) at time zone 'Asia/Kolkata')::date original_payment_date
    from public.srk_company_commission_refund_reconciliations r
    join public.service_bookings b on b.id=r.booking_id
    where (r.recorded_at at time zone 'Asia/Kolkata')::date between v_start and v_end
  )
  select jsonb_build_object(
    'period',p_period,'start_date',v_start,'end_date',v_end,
    'commission_refund_total_recorded_in_period',
      coalesce(sum(commission_refund_amount),0)::numeric(14,2),
    'refunds_against_same_period_bookings',
      coalesce(sum(commission_refund_amount) filter(where original_payment_date between v_start and v_end),0)::numeric(14,2),
    'refunds_against_prior_period_bookings',
      coalesce(sum(commission_refund_amount) filter(where original_payment_date < v_start),0)::numeric(14,2),
    'refunds_against_future_dated_bookings',
      coalesce(sum(commission_refund_amount) filter(where original_payment_date > v_end),0)::numeric(14,2),
    'reconciliation_count',count(*)::int
  ) into v_result
  from refund_period;

  return v_result;
end;
$$;
revoke all on function public.srk_admin_commission_refund_period_breakdown(text,date) from public, anon;
grant execute on function public.srk_admin_commission_refund_period_breakdown(text,date) to authenticated;

create table if not exists public.srk_company_commission_refund_reconciliation_history (
  id uuid primary key default gen_random_uuid(),
  reconciliation_id uuid not null references public.srk_company_commission_refund_reconciliations(id) on delete restrict,
  refund_request_id uuid not null,
  booking_id uuid not null,
  action text not null check (action in ('created','updated')),
  old_commission_refund_amount numeric,
  new_commission_refund_amount numeric not null,
  old_admin_note text,
  new_admin_note text not null,
  old_recorded_by uuid,
  new_recorded_by uuid not null,
  original_recorded_at timestamptz not null,
  changed_by uuid,
  changed_at timestamptz not null default clock_timestamp()
);

create index if not exists srk_company_comm_refund_history_lookup_idx
on public.srk_company_commission_refund_reconciliation_history
(refund_request_id, changed_at desc);

alter table public.srk_company_commission_refund_reconciliation_history enable row level security;
drop policy if exists srk_company_commission_refund_history_admin_read
