create or replace function public.srk_guard_company_commission_refund_credit_total()
returns trigger language plpgsql security definer
set search_path to 'pg_catalog','public'
as $$
declare v_allocated numeric(14,2);
begin
 select coalesce(sum(a.amount),0)::numeric(14,2) into v_allocated
 from public.srk_worker_cash_commission_refund_allocations a
 where a.refund_request_id=new.refund_request_id;
 if v_allocated>new.commission_refund_amount then
  raise exception 'Company commission refund cannot be reduced below worker cash commission credits already issued';
 end if;
 return new;
end
$$;
drop trigger if exists srk_guard_company_commission_refund_credit_total_trg
 on public.srk_company_commission_refund_reconciliations;
create trigger srk_guard_company_commission_refund_credit_total_trg
before update of commission_refund_amount on public.srk_company_commission_refund_reconciliations
for each row execute function public.srk_guard_company_commission_refund_credit_total();
revoke all on function public.srk_guard_company_commission_refund_credit_total() from public,anon,authenticated;

do $$
declare v_def text; v_old text; v_new text;
begin
 v_old:=$old$entry_type in ('cash_commission_due','cash_commission_collected')$old$;
 v_new:=$new$entry_type in ('cash_commission_due','cash_commission_collected','cash_commission_refund_credit')$new$;
 v_def:=pg_get_functiondef('public.srk_admin_finance_dashboard(text,date)'::regprocedure);
 if position(v_old in v_def)=0 then
  raise exception 'Expected cash commission dashboard expression not found; no change made';
 end if;
 v_def:=replace(v_def,v_old,v_new);
 execute v_def;
end
$$;

create or replace function public.srk_admin_mark_worker_payout_paid(
 p_payout_id uuid,
 p_payment_method text,
 p_payment_reference text,
 p_note text default null
)
returns public.srk_worker_payout_requests
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_payout public.srk_worker_payout_requests%rowtype;
 v_available numeric(14,2);
 v_reserved numeric(14,2);
 v_left numeric(14,2);
 v_earning record;
 v_alloc numeric(14,2);
 v_total_allocated numeric(14,2):=0;
begin
 if auth.uid() is null or not public.srk_has_admin_permission('payouts.manage') then
  raise exception 'Payout management permission required' using errcode='42501';
 end if;
 if nullif(btrim(p_payment_reference),'') is null then raise exception 'UTR/transaction reference required'; end if;
 if p_payment_method not in ('upi','bank_transfer','phonepe','other') then raise exception 'Invalid payout method'; end if;

 select * into v_payout from public.srk_worker_payout_requests where id=p_payout_id for update;
 if not found or v_payout.status<>'approved' then raise exception 'Only approved payout can be marked paid'; end if;
 perform 1 from public.srk_worker_profiles where id=v_payout.worker_id for update;
 if exists(select 1 from public.srk_worker_earnings where worker_id=v_payout.worker_id and settlement_status='held') then
  raise exception 'Worker payout is held due to refund/dispute review';
 end if;

 select coalesce(sum(balance_effect),0) into v_available
 from public.srk_worker_wallet_ledger where worker_id=v_payout.worker_id;
 select coalesce(sum(coalesce(approved_amount,requested_amount)),0) into v_reserved
 from public.srk_worker_payout_requests
 where worker_id=v_payout.worker_id and id<>p_payout_id and status in ('requested','under_review','approved');
 if v_payout.approved_amount>v_available-v_reserved then
  raise exception 'Wallet balance changed; payout cannot be paid';
 end if;

 -- Only money actually payable through the online wallet is eligible:
 -- online earnings net of worker refund adjustments, plus cash-commission
 -- refunds specifically credited back to this worker. Cash job earnings
 -- themselves are already received directly by the worker and must not be
 -- paid a second time from the online wallet. Company cash-commission dues
 -- are debt entries, not earning allocations.
 v_left:=v_payout.approved_amount;
 for v_earning in
  select e.id,e.booking_id,e.worker_id,
    (
      case
       when lower(coalesce(e.payment_method,'')) in ('online','upi','card') then
        coalesce((select sum(l.balance_effect) from public.srk_worker_wallet_ledger l
          where l.earning_id=e.id and l.entry_type in ('earning','refund_adjustment')),0)
       when lower(coalesce(e.payment_method,''))='cash' then
        coalesce((select sum(l.balance_effect) from public.srk_worker_wallet_ledger l
          where l.earning_id=e.id and l.entry_type='cash_commission_refund_credit'),0)
       else 0
      end
      - coalesce((select sum(a.allocated_amount) from public.srk_worker_payout_earning_allocations a
        where a.earning_id=e.id),0)
    ) as remaining
  from public.srk_worker_earnings e
  where e.worker_id=v_payout.worker_id
  order by e.created_at,e.id
  for update
 loop
  exit when v_left<=0;
  if v_earning.remaining>0 then
   v_alloc:=least(v_left,v_earning.remaining);
   insert into public.srk_worker_payout_earning_allocations
    (payout_request_id,earning_id,booking_id,worker_id,allocated_amount)
   values(p_payout_id,v_earning.id,v_earning.booking_id,v_earning.worker_id,v_alloc);
   v_left:=v_left-v_alloc;
   v_total_allocated:=v_total_allocated+v_alloc;
  end if;
 end loop;
 if v_left>0 then
  raise exception 'Payout exceeds traceable online earnings or cash-commission refund credits; reconcile wallet before paying';
 end if;

 insert into public.srk_worker_wallet_ledger(worker_id,entry_type,amount,balance_effect,description,reference_id,idempotency_key)
 values(v_payout.worker_id,'payout_paid',v_payout.approved_amount,-v_payout.approved_amount,
  'Admin verified payout with earning-level allocation',p_payment_reference,'payout-paid:'||v_payout.id::text)
 on conflict(idempotency_key) do nothing;

 update public.srk_worker_payout_requests
 set status='paid',payment_method=p_payment_method,payment_reference=p_payment_reference,
  admin_note=coalesce(p_note,admin_note),paid_at=clock_timestamp()
 where id=p_payout_id returning * into v_payout;
 return v_payout;
end
$function$;

revoke all on function public.srk_admin_mark_worker_payout_paid(uuid,text,text,text) from public,anon;
grant execute on function public.srk_admin_mark_worker_payout_paid(uuid,text,text,text) to authenticated,service_role;

create or replace function public.srk_confirm_cash_payment(
 p_booking_id uuid,
 p_amount numeric,
 p_note text default null
)
returns boolean
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_role text;
 v_bill numeric(12,2);
 v_customer uuid;
 v_booking_status text;
 v_payment_method text;
 v_payment_status text;
 v_worker boolean;
 v_customer_confirmed boolean;
 v_worker_confirmed boolean;
 v_forced_online integer;
begin
 if auth.uid() is null then
  raise exception 'Authentication required';
 end if;

 select customer_user_id,status,payment_method,payment_status
 into v_customer,v_booking_status,v_payment_method,v_payment_status
 from public.service_bookings
 where id=p_booking_id
 for update;

 if not found then raise exception 'Booking not found'; end if;
 if v_booking_status<>'completed' then
  raise exception 'Customer must confirm completed work before cash payment';
 end if;
 if lower(btrim(coalesce(v_payment_method,''))) not in ('cash','नकद (cash)','नकद') then
  raise exception 'Cash confirmation is allowed only when Cash was selected for this booking';
 end if;
 if lower(coalesce(v_payment_status,'')) in ('paid','completed','refunded') then
  raise exception 'Booking payment is already completed or refunded';
 end if;

 if v_customer=auth.uid() then
  v_role:='customer';
 else
  select exists(
   select 1
   from public.srk_booking_workers bw
   join public.srk_worker_profiles wp on wp.id=bw.worker_id
   where bw.booking_id=p_booking_id
    and bw.worker_role='technician'
    and wp.user_id=auth.uid()
    and bw.assignment_status in ('assigned','working','paused','completed')
  ) into v_worker;

  if not v_worker then
   raise exception 'Only booking customer or assigned Technician can confirm cash';
  end if;
  v_role:='technician';
 end if;

 select total_amount into v_bill
 from public.srk_booking_final_bills
 where booking_id=p_booking_id and status in ('issued','approved');

 if v_bill is null then raise exception 'Final bill is not issued'; end if;
 if p_amount is null or p_amount<>v_bill then
  raise exception 'Cash confirmation must match final bill amount';
 end if;

 select count(*) into v_forced_online
 from public.srk_technician_booking_sequence s
 where s.booking_id=p_booking_id
  and mod(s.sequence_number,3)=0;

 if v_forced_online>0 then
  raise exception 'This technician booking requires online payment';
 end if;

 if not exists(
  select 1 from public.srk_booking_payment_evidence
  where booking_id=p_booking_id
   and payer_role=v_role
   and payment_method='cash'
   and amount=v_bill
   and verification_status='verified'
 ) then
  insert into public.srk_booking_payment_evidence(
   booking_id,submitted_by,payer_role,payment_method,amount,verification_status,note
  )
  values(p_booking_id,auth.uid(),v_role,'cash',p_amount,'verified',p_note);
 end if;

 select
  exists(
   select 1 from public.srk_booking_payment_evidence
   where booking_id=p_booking_id and payer_role='customer'
    and payment_method='cash' and amount=v_bill and verification_status='verified'
  ),
  exists(
   select 1 from public.srk_booking_payment_evidence
   where booking_id=p_booking_id and payer_role='technician'
    and payment_method='cash' and amount=v_bill and verification_status='verified'
  )
 into v_customer_confirmed,v_worker_confirmed;

 if v_customer_confirmed and v_worker_confirmed then
  update public.service_bookings
  set payment_status='paid',amount_paid=v_bill,payment_verified_at=clock_timestamp()
  where id=p_booking_id;
  return true;
 end if;

 return false;
end
$function$;

revoke all on function public.srk_confirm_cash_payment(uuid,numeric,text) from public,anon;
grant execute on function public.srk_confirm_cash_payment(uuid,numeric,text) to authenticated,service_role;

create or replace function public.srk_customer_create_booking(
 p_category_id uuid,
 p_service_type_id uuid,
 p_skill_id uuid,
 p_technician_count integer,
 p_helper_count integer,
 p_duration_hours integer,
 p_state text,
 p_district text,
 p_pincode text,
 p_address text,
 p_booking_latitude double precision,
 p_booking_longitude double precision,
 p_current_gps_latitude double precision default null,
 p_current_gps_longitude double precision default null
)
returns public.service_bookings
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_customer public.srk_customer_profiles%rowtype;
 v_service public.srk_service_types%rowtype;
 v_booking public.service_bookings%rowtype;
begin
 if auth.uid() is null then raise exception 'OTP login required'; end if;
 select * into v_customer from public.srk_customer_profiles where user_id=auth.uid();
 if not found then raise exception 'Complete customer profile before booking'; end if;
 if v_customer.account_status<>'active' then raise exception 'Customer account is restricted from new bookings'; end if;
 if p_technician_count not between 1 and 20 or p_helper_count not between 0 and 20 then raise exception 'Invalid worker count'; end if;
 if p_duration_hours not between 1 and 1440 then raise exception 'Duration must be 1 hour to 60 days'; end if;
 if p_pincode !~ '^[0-9]{6}$' or nullif(btrim(p_state),'') is null or nullif(btrim(p_district),'') is null or nullif(btrim(p_address),'') is null then
  raise exception 'Complete valid booking address required';
 end if;
 if p_booking_latitude is null or p_booking_longitude is null or p_booking_latitude not between -90 and 90 or p_booking_longitude not between -180 and 180 then
  raise exception 'Booking Address GPS coordinates required';
 end if;
 if (p_current_gps_latitude is null)<>(p_current_gps_longitude is null) then raise exception 'Current GPS coordinates must be supplied together'; end if;
 select * into v_service from public.srk_service_types where id=p_service_type_id and category_id=p_category_id and is_active;
 if not found then raise exception 'Service does not belong to active category'; end if;
 if not exists(select 1 from public.srk_service_skills where id=p_skill_id and service_type_id=p_service_type_id and is_active) then
  raise exception 'Work/skill does not belong to selected service';
 end if;

 insert into public.service_bookings(customer_name,phone,state,district,pincode,address,service_type,payment_method,status,
  commission_rate,materials_amount,customer_user_id,customer_id,category_id,service_type_id,selected_skill_id,
  requested_technician_count,requested_helper_count,requested_duration_hours,booking_latitude,booking_longitude,
  location_lat,location_lng,booking_address_confirmed_at)
 values(v_customer.full_name,v_customer.phone,btrim(p_state),btrim(p_district),p_pincode,btrim(p_address),v_service.service_name,
  'Unselected','new',15.00,0,auth.uid(),v_customer.id,p_category_id,p_service_type_id,p_skill_id,
  p_technician_count,p_helper_count,p_duration_hours,p_booking_latitude,p_booking_longitude,
  p_current_gps_latitude,p_current_gps_longitude,clock_timestamp())
 returning * into v_booking;

 insert into public.srk_booking_matching_queue(booking_id,queue_status) values(v_booking.id,'pending');
 return v_booking;
end
$function$;

revoke all on function public.srk_customer_create_booking(uuid,uuid,uuid,integer,integer,integer,text,text,text,text,double precision,double precision,double precision,double precision) from public,anon;
grant execute on function public.srk_customer_create_booking(uuid,uuid,uuid,integer,integer,integer,text,text,text,text,double precision,double precision,double precision,double precision) to authenticated,service_role;

alter table public.service_bookings
  alter column payment_method set default 'Unselected';

comment on column public.service_bookings.payment_method is
'Customer-selected payment method after final bill; new bookings default to Unselected. Legacy rows retain their stored value.';

create or replace function public.srk_customer_choose_payment_method(
 p_booking_id uuid,
 p_method text
)
returns public.service_bookings
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_booking public.service_bookings%rowtype;
 v_method text;
 v_forced_online boolean;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 v_method:=lower(btrim(coalesce(p_method,'')));
 if v_method not in ('cash','online','upi','card') then
  raise exception 'Choose Cash, Online, UPI or Card';
 end if;
 select * into v_booking from public.service_bookings
 where id=p_booking_id and customer_user_id=auth.uid() for update;
 if not found then raise exception 'Customer booking not found'; end if;
 if v_booking.status<>'completed' then
  raise exception 'Payment can be selected after customer confirms completed work';
 end if;
 if lower(coalesce(v_booking.payment_status,'')) in ('paid','completed','refunded') then
  raise exception 'Payment is already completed or refunded';
 end if;
 if not exists(select 1 from public.srk_booking_final_bills
  where booking_id=p_booking_id and status in ('issued','approved')) then
  raise exception 'Final bill is not available';
 end if;
 select exists(select 1 from public.srk_technician_booking_sequence s
  where s.booking_id=p_booking_id and mod(s.sequence_number,3)=0)
 into v_forced_online;
 if v_forced_online and v_method='cash' then
  raise exception 'This technician booking requires online payment';
 end if;
 if v_booking.razorpay_payment_id is not null then
  raise exception 'A Razorpay payment is already linked; payment method cannot be changed';
 end if;
 if v_booking.razorpay_order_id is not null and
  lower(coalesce(v_booking.payment_method,'')) <>
  (case v_method when 'upi' then 'upi' when 'card' then 'card' when 'cash' then 'cash' else 'online' end) then
  raise exception 'A payment order already exists; payment method cannot be changed until reconciliation';
 end if;
 update public.service_bookings
 set payment_method=case when v_method='upi' then 'UPI'
  when v_method='card' then 'Card' when v_method='cash' then 'Cash' else 'Online' end
 where id=p_booking_id returning * into v_booking;
 return v_booking;
end;
$function$;
revoke all on function public.srk_customer_choose_payment_method(uuid,text) from public,anon;
grant execute on function public.srk_customer_choose_payment_method(uuid,text) to authenticated,service_role;
